INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Addressee of the representation letter
(1, 'Written Representations', 'During the 2025 audit of Oakwood Industries, the controller prepares the management representation letter and asks the engagement team at Fletcher & Caldwell CPA to whom the letter should be addressed. Under AU-C 580, the management representation letter should be addressed to:', '["The entity''s board of directors or audit committee", "The auditor (i.e., the engagement partner or the firm)", "The SEC or other applicable regulatory body", "The entity''s external legal counsel"]'::jsonb, 1, 'AU-C 580.15 requires the management representation letter to be addressed to the auditor. The letter is a communication from management confirming matters discussed during the audit and supporting other audit evidence. Unlike board communications, the representation letter is directed to the engagement partner or the audit firm, not to the audit committee or external regulators.', 'medium', 2),

-- Q2: easy / L1 — Definition of written representations
(1, 'Written Representations', 'Under AU-C 580, written representations are best described as:', '["Written statements by management provided to the auditor to confirm certain matters or support other audit evidence", "Formal affidavits filed with regulatory agencies certifying compliance with securities laws", "Internal memoranda prepared by the audit team summarizing conclusions reached during fieldwork", "Legal opinions issued by the entity''s external counsel regarding pending litigation"]'::jsonb, 0, 'AU-C 580.03 defines written representations as written statements by management provided to the auditor to confirm certain matters or to support other audit evidence. They are a form of audit evidence, not regulatory filings. Unlike internal audit memoranda, written representations originate from management and are directed to the auditor as formal confirmations.', 'easy', 1),

-- Q3: easy / L1 — Management responsibility for financial statements
(1, 'Written Representations', 'In the management representation letter, management''s acknowledgment of responsibility for the financial statements confirms that:', '["The auditor has verified every transaction recorded in the general ledger", "The audit committee approved all journal entries posted during the fiscal year", "Management is responsible for the preparation and fair presentation of the financial statements", "The external auditor assumes joint responsibility for detecting all material fraud"]'::jsonb, 2, 'AU-C 580.10 requires management to acknowledge its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. This reinforces that financial statements are management''s responsibility, not the auditor''s. The auditor does not verify every transaction or assume joint responsibility for fraud detection.', 'easy', 1),

-- Q4: medium / L2 — Period covered by representation letter
(1, 'Written Representations', 'During the audit of Briarstone Technologies for the year ended December 31, 2025, the staff auditor at Monroe & Pace CPA asks what period the management representation letter should cover. Under AU-C 580, the representation letter should cover:', '["Only the fourth quarter of the fiscal year since that period has the highest transaction volume", "The twelve months preceding the date the representation letter is signed", "Only the period from the beginning of fieldwork through the report release date", "All periods referred to in the auditor''s report"]'::jsonb, 3, 'AU-C 580.15 states that the written representation letter should cover all periods referred to in the auditor''s report. If the auditor is reporting on comparative financial statements for 2024 and 2025, the letter must cover both years. It is not limited to the most recent quarter or the fieldwork period; it encompasses all financial statement periods under audit.', 'medium', 2),

-- Q5: hard / L3 — Contradictory evidence and written representations
(1, 'Written Representations', 'During the 2025 audit of Silverbrook Capital, the engagement team at Hayward & Foster discovers that subsidiary financial records contradict management''s written representation that all intercompany balances have been properly eliminated. The team has already obtained the signed representation letter. Under AU-C 580, the auditor should:', '["Investigate the inconsistency, reconsider the reliability of the representations, and determine whether additional audit procedures are necessary", "Accept the written representation as sufficient because it was signed by the CEO and CFO before the contradiction was discovered", "Immediately withdraw from the engagement since contradictory evidence invalidates all representations", "Issue the audit report with an emphasis-of-matter paragraph noting the inconsistency"]'::jsonb, 0, 'AU-C 580.17 requires the auditor to investigate inconsistencies between written representations and other audit evidence, reconsider their reliability, and take appropriate action such as performing additional procedures. Written representations do not override contradictory evidence regardless of the signatories. Immediate withdrawal is not required; the auditor must first evaluate the nature and significance of the inconsistency.', 'hard', 3),

-- Q6: medium / L3 — Uncorrected misstatements representation
(1, 'Written Representations', 'At the conclusion of the 2025 audit of Redfield Manufacturing, the engagement partner at Carlton & Webb identifies three uncorrected misstatements totaling $45,000, which are individually and in aggregate immaterial. The partner must ensure the management representation letter addresses these items. Under AU-C 580, management''s representation regarding uncorrected misstatements should state that:', '["The auditor has agreed to waive all detected misstatements below the materiality threshold", "Management believes the effects of the uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole", "All misstatements have been corrected and no adjustments remain outstanding", "The auditor is solely responsible for determining whether uncorrected misstatements are material"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of these items is typically attached to the representation letter. This is distinct from stating that all misstatements were corrected; the representation acknowledges items that remain unadjusted while affirming their immateriality.', 'medium', 3),

-- Q7: medium / L2 — Representations as necessary but not sufficient evidence
(1, 'Written Representations', 'During the 2025 audit of Northgate Logistics, a junior associate at Pemberton & Shaw suggests that because management confirmed inventory existence in the representation letter, no further substantive procedures are needed. The engagement partner disagrees. Under AU-C 580, this is because written representations:', '["May only address qualitative matters and cannot provide evidence about quantitative assertions", "Are inadmissible as audit evidence and serve only an administrative purpose", "Are necessary audit evidence but do not provide sufficient appropriate evidence on their own for any assertion", "Are only required when the auditor has identified a material weakness in internal controls"]'::jsonb, 2, 'AU-C 580.04 states that written representations are necessary audit evidence but do not provide sufficient appropriate audit evidence on their own about any of the matters with which they deal. The auditor must corroborate representations with other procedures such as observation, inspection, or confirmation. Representations cannot substitute for substantive testing regardless of how specific management''s assurances are.', 'medium', 2),

-- Q8: medium / L2 — Access to records representation
(1, 'Written Representations', 'Before issuing the 2025 audit report for Crestline Holdings, the engagement partner at Wilkins & Associates prepares the management representation letter and includes a standard representation about information access. Under AU-C 580, management should represent that it has provided the auditor with:', '["Only those records that the auditor specifically requested during fieldwork", "Copies of all board meeting minutes from the past five fiscal years", "A listing of every employee who accessed the accounting system during the audit period", "Access to all information relevant to the preparation and fair presentation of the financial statements"]'::jsonb, 3, 'AU-C 580.10 requires management to represent that it has provided the auditor with access to all information of which management is aware that is relevant to the preparation and fair presentation of the financial statements. This includes records, documentation, and other matters. The representation is broader than specifically requested records; it encompasses all relevant information, ensuring the auditor has not been denied access to pertinent data.', 'medium', 2),

-- Q9: easy / L1 — Oral vs. written representations
(1, 'Written Representations', 'Under AU-C 580, why must the auditor obtain management representations in written form rather than relying solely on oral assurances?', '["Oral representations are prohibited by GAAS under all circumstances", "Written representations are less expensive to obtain than oral statements", "Oral representations cannot be made under oath and therefore lack legal standing", "Written representations reduce misunderstandings and provide documented audit evidence"]'::jsonb, 3, 'AU-C 580.08 requires written representations because they reduce the possibility of misunderstanding between management and the auditor and provide a documented record that serves as audit evidence. Oral representations are not prohibited by GAAS; the auditor routinely obtains oral information through inquiry. However, for matters requiring formal confirmation, the written form ensures clarity and reliable documentation.', 'easy', 1),

-- Q10: easy / L1 — Completeness representation
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should include a representation about the completeness of:', '["All transactions that have been recorded and are reflected in the financial statements", "The auditor''s workpapers and supporting schedules", "Tax returns filed by the entity over the past three years", "The engagement letter terms agreed upon at the start of the audit"]'::jsonb, 0, 'AU-C 580.10-11 requires management to represent that all transactions have been recorded and are reflected in the financial statements, confirming completeness of information. This ensures the auditor has a complete picture of the entity''s financial position. The representation does not address auditor workpapers, tax filings, or engagement letter terms, which are separate matters outside the scope of AU-C 580.', 'easy', 1),

-- Q11: easy / L1 — Accounting policies representation
(1, 'Written Representations', 'Under AU-C 580, what is a required management representation regarding accounting policies?', '["The entity''s policies have been reviewed and approved by the SEC or other regulatory body", "The selection and application of accounting policies are appropriate for the entity", "All accounting policies were developed without any input from external consultants", "The entity''s policies remain unchanged from the prior year in every respect"]'::jsonb, 1, 'AU-C 580.10 requires management to represent that the selection and application of accounting policies are appropriate under the applicable financial reporting framework. This confirms management''s judgment in choosing policies that faithfully represent the entity''s transactions. The representation does not require regulatory approval or prohibit external consultant input; it affirms that chosen policies are suitable for the entity''s circumstances.', 'easy', 1),

-- Q12: hard / L4 — Group audit representation letters from component management
(1, 'Written Representations', 'Henley & Whitmore CPA is the group engagement partner for the 2025 consolidated audit of Avalon Global Inc., which has three foreign subsidiaries with separate component auditors. The group engagement team must determine what written representations are needed from component management. Under AU-C 600 and AU-C 580, the group engagement partner should:', '["Rely solely on the parent company''s representation letter since it covers all consolidated entities", "Require only the component auditors to sign representation letters on behalf of their component management", "Forego component representation letters if the component auditors have issued unmodified opinions", "Obtain written representations from component management or request component auditors to obtain them on the group engagement team''s behalf"]'::jsonb, 3, 'AU-C 600.40 requires the group engagement team to request component management to provide written representations, or to request component auditors to obtain such representations on the group team''s behalf. The parent company''s letter alone is insufficient because component management has direct knowledge of subsidiary-specific matters. Component auditor opinions do not substitute for management representations about completeness, fraud, and related party disclosures at the subsidiary level.', 'hard', 4),

-- Q13: easy / L2 — Compliance with laws representation
(1, 'Written Representations', 'During the 2025 audit of Bayside Hospitality Group, the engagement team at Crawford & Ellis prepares the management representation letter. The team includes a representation about legal compliance. Under AU-C 580, management should represent that:', '["The entity has never been subject to any regulatory investigation or enforcement action", "All employees have received annual compliance training as required by federal law", "All known instances of noncompliance or suspected noncompliance with laws and regulations have been disclosed to the auditor", "The entity''s legal counsel has certified that no violations of law occurred during the fiscal year"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements have been disclosed to the auditor. This does not guarantee zero violations or require legal counsel certification; it ensures the auditor is informed of known compliance issues that could affect the financial statements.', 'easy', 2),

-- Q14: medium / L3 — Plans/intentions affecting carrying values
(1, 'Written Representations', 'During the 2025 audit of Cedarwood Electronics, management informs the engagement team at Greystone & Associates that it plans to discontinue a product line and close two manufacturing facilities. The auditor considers how this affects the representation letter. Under AU-C 580, the auditor should obtain a specific written representation about management''s plans and intentions when those plans:', '["Have already been publicly announced in a press release and are therefore common knowledge", "Involve only immaterial asset values that fall below the planning materiality threshold", "May affect the carrying value or classification of assets and liabilities in the financial statements", "Require approval from the entity''s board of directors before they can be implemented"]'::jsonb, 2, 'AU-C 580.A31 indicates that the auditor should obtain written representations about management''s plans and intentions when those plans may affect the carrying value or classification of assets and liabilities. Planned facility closures could trigger impairment charges or reclassifications. Public announcement does not eliminate the need for formal representation, and the requirement applies regardless of board approval status since management''s stated intentions directly affect financial statement measurements.', 'medium', 3),

-- Q15: hard / L4 — Evaluating contradictory evidence against representations
(1, 'Written Representations', 'During the 2025 audit of Westbridge Financial Group, the engagement team at Ashton & Clarke discovers that management''s written representation states no material contingent liabilities exist beyond those disclosed. However, the auditor''s review of board minutes reveals a $2.8 million environmental remediation demand letter received before year-end that was not disclosed. The auditor should evaluate whether:', '["The representation letter can be amended with a footnote acknowledging the remediation demand while keeping the original text unchanged", "An emphasis-of-matter paragraph is sufficient to address the undisclosed contingent liability without further investigation", "The undisclosed demand letter qualifies as a scope limitation that automatically requires a qualified opinion", "The contradictory evidence indicates management''s representations may be unreliable, necessitating reassessment of all representations and their effect on the audit"]'::jsonb, 3, 'AU-C 580.18-19 requires the auditor to take appropriate action when contradictory evidence exists. Discovery that management failed to disclose a material contingent liability raises doubt about the reliability of all representations. The auditor must reassess whether other representations are trustworthy and determine the effect on the overall audit. Simply amending the letter or adding an emphasis-of-matter paragraph would not address the underlying reliability concern, which may indicate a pervasive integrity issue.', 'hard', 4),

-- Q16: medium / L2 — Accounting estimates representation
(1, 'Written Representations', 'During the 2025 audit of Pineridge Development Corp., the engagement team at Larchmont & Brooks reviews management''s allowance for doubtful accounts, which involves significant estimation. The team drafts the management representation letter and considers what representation is needed for estimates. Under AU-C 580, management should represent that:', '["The methods, data, and significant assumptions used in making accounting estimates are reasonable in the circumstances", "All accounting estimates were prepared by an independent third-party valuation specialist", "No estimation uncertainty exists because management used industry-standard calculation formulas", "The auditor has approved all significant estimates and concurs with the amounts reported"]'::jsonb, 0, 'AU-C 580.A30 provides that the auditor may obtain representations regarding the reasonableness of significant assumptions, including whether they appropriately reflect management''s intent and ability to carry out specific courses of action. Management represents that its methods, data, and assumptions are reasonable. Estimates need not be prepared by an external specialist, and the auditor does not approve estimates but evaluates them independently.', 'medium', 2),

-- Q17: easy / L1 — Title to assets representation
(1, 'Written Representations', 'Under AU-C 580, which assertion does the management representation about title and rights to assets primarily support?', '["Existence of assets recorded on the balance sheet", "Rights and obligations related to assets held by the entity", "Completeness of all asset transactions during the period", "Valuation and allocation of asset carrying amounts"]'::jsonb, 1, 'AU-C 580.11 includes a representation that the entity has satisfactory title to or rights over all assets, which directly supports the rights and obligations assertion. This confirms that assets on the balance sheet are owned or controlled by the entity. Unlike existence (which confirms the asset is real) or valuation (which confirms the amount), the title representation specifically addresses legal ownership and contractual rights to use the assets.', 'easy', 1),

-- Q18: medium / L3 — Side agreements representation
(1, 'Written Representations', 'During the 2025 audit of Kensington Properties LLC, the engagement team at Stratford & Cole discovers evidence suggesting that the client may have informal side agreements with certain tenants that modify the terms of recorded leases. The auditor should request a written representation about side agreements because:', '["AU-C 580 prohibits management from entering into any informal agreements that are not documented in the general ledger", "The auditor is required to obtain legal opinions for every lease agreement before issuing the audit report", "Side agreements are always immaterial and only need to be disclosed in the management representation letter", "Undisclosed side agreements could materially affect lease revenue recognition, and the representation helps ensure completeness of information provided to the auditor"]'::jsonb, 3, 'AU-C 580.A14 supports obtaining specific representations when the auditor suspects undisclosed arrangements. Side agreements can modify lease terms, affecting revenue recognition, asset classification, and liability measurement. The representation helps ensure management has disclosed all relevant information. Side agreements are not always immaterial; they may create off-balance-sheet obligations or alter the timing and amount of recognized revenue, making disclosure to the auditor essential.', 'medium', 3),

-- Q19: easy / L1 — Subsequent events representation
(1, 'Written Representations', 'Under AU-C 580, which of the following is a required representation regarding events after the balance sheet date?', '["Management certifies that no events occurred between year-end and the report date under any circumstances", "The auditor personally monitored all entity transactions during the subsequent period", "Management has disclosed all events occurring after the balance sheet date that require adjustment or disclosure", "The board of directors independently verified that no subsequent events affect the financial statements"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that all events occurring subsequent to the date of the financial statements for which the applicable financial reporting framework requires adjustment or disclosure have been adjusted or disclosed. Management cannot certify no events occurred; the representation confirms proper treatment of those that did. The representation comes from management, not the board, and the auditor does not personally monitor all subsequent transactions.', 'easy', 1),

-- Q20: easy / L1 — Internal control responsibility representation
(1, 'Written Representations', 'Under AU-C 580, which matter must management acknowledge in the written representation letter regarding internal controls?', '["The auditor designed and implemented all internal controls over financial reporting", "No control deficiencies existed at any point during the fiscal year", "All internal controls were tested by an independent third party before year-end", "Management is responsible for the design, implementation, and maintenance of internal controls relevant to financial reporting"]'::jsonb, 3, 'AU-C 580.10 requires management to acknowledge responsibility for the design, implementation, and maintenance of internal controls relevant to the preparation and fair presentation of financial statements. This reinforces that internal controls are management''s responsibility, not the auditor''s. The representation does not claim zero deficiencies or require third-party testing; it confirms management''s ownership of the control environment.', 'easy', 1),

-- Q21: medium / L2 — Updating representation for reissued report
(1, 'Written Representations', 'Thornton Manufacturing requests that the engagement team at Irving & Holt CPA reissue the 2024 auditor''s report to include in a loan application filed in October 2025. The auditor must address the management representation letter before reissuance. Under AU-C 560, when reissuing a report, the auditor should:', '["Use the original representation letter without modification since the audit has already been completed", "Obtain an updated written representation letter from management addressing any events between the original report date and the reissuance date", "Rely on oral assurances from management that no material changes have occurred since the original report date", "Require the audit committee to provide a supplemental representation letter covering the reissuance period"]'::jsonb, 1, 'AU-C 560.14-15 requires the auditor to perform procedures and obtain updated written representations from management regarding events between the original report date and the reissuance date. The original representation letter is insufficient because new information may have arisen. Oral assurances do not satisfy the requirement for written representations, and the letter comes from management, not the audit committee.', 'medium', 2),

-- Q22: medium / L3 — Going concern specific representations
(1, 'Written Representations', 'During the 2025 audit of Bayfield Industries, the engagement team at Palmer & Duncan identifies conditions that raise substantial doubt about the entity''s ability to continue as a going concern. Management asserts it has viable plans to mitigate the risk. Under AU-C 570 and AU-C 580, the auditor should obtain a specific written representation addressing:', '["Management''s plans and their feasibility to mitigate the going concern conditions, including the completeness of disclosures about those plans", "A bank commitment letter confirming that financing will remain available for the next twelve months", "Certification from the board of directors that the entity will not file for bankruptcy in the upcoming fiscal year", "An insurance policy covering potential losses arising from the going concern conditions"]'::jsonb, 0, 'AU-C 570.A24 and AU-C 580.A31 require the auditor to obtain specific representations about management''s plans intended to mitigate going concern conditions and the completeness of related disclosures. The representation documents management''s assessment and stated plans, allowing the auditor to evaluate feasibility. A bank guarantee, board certification, or insurance policy may be relevant evidence but are not substitutes for management''s own written representation about its plans.', 'medium', 3),

-- Q23: medium / L3 — Contingent liabilities representation
(1, 'Written Representations', 'During the 2025 audit of Stonewall Contracting Inc., the engagement team at Harmon & Pearce discovers three pending construction defect lawsuits totaling $4.2 million. Management provides explanations but has not recorded or disclosed any amounts. The auditor should ensure the representation letter specifically includes:', '["A statement from legal counsel that all lawsuits will be resolved in the entity''s favor", "Management''s commitment to settle all outstanding litigation before the audit report is issued", "Management''s assessment of the likelihood and estimated range of potential loss for each contingent liability, and confirmation that all known litigation has been disclosed", "An indemnification clause protecting the auditor from liability if the litigation disclosures prove inadequate"]'::jsonb, 2, 'AU-C 580.11 and AU-C 501 require management to represent that all known litigation, claims, and assessments have been disclosed and that management''s assessment of the likelihood of loss is reflected in the financial statements. The representation must address both completeness of disclosure and management''s judgment about probable outcomes. Legal counsel predictions or settlement commitments are not substitutes for management''s own formal assessment of contingent liabilities.', 'medium', 3),

-- Q24: medium / L2 — Documentation of refusal and its consequences
(1, 'Written Representations', 'During the 2025 audit of Clearpoint Energy Corp., management''s CEO refuses to sign the representation letter, citing concerns about personal legal liability. The CFO offers to sign alone. The engagement partner at Wallace & Burke must decide how to proceed. Under AU-C 580, the auditor should:', '["Accept the CFO''s signature alone since either officer may individually provide representations", "Evaluate whether the CEO''s refusal constitutes a scope limitation and consider the effect on the audit opinion", "Request the audit committee chair to sign the representation letter in place of the CEO", "Proceed with issuing an unmodified opinion since the CFO''s signature provides adequate coverage"]'::jsonb, 1, 'AU-C 580.19-20 requires the auditor to evaluate the effect when management refuses to provide requested written representations. The CEO''s refusal to sign may constitute a scope limitation, which could require a qualified opinion or disclaimer. The representation letter should be signed by management with appropriate responsibilities, typically both CEO and CFO. Simply substituting the audit committee chair or accepting only one signature without evaluating the implications does not satisfy the standard.', 'medium', 2),

-- Q25: hard / L4 — Management integrity and representation reliability
(1, 'Written Representations', 'During the 2025 audit of Northfield Capital Partners, the engagement team at Sullivan & Greer discovers that the CEO provided materially false information about a related-party transaction during the inquiry phase. The CEO later signed the representation letter confirming no undisclosed related-party transactions. The engagement team must assess the broader implications. Under AU-C 580, the most significant concern is that:', '["The representation letter is automatically void because one representation was demonstrably false", "The auditor must immediately report the false representation to law enforcement authorities", "Management''s lack of integrity raises doubt about the reliability of all representations, which may make it impossible to obtain sufficient appropriate audit evidence", "The false representation can be cured by obtaining a corrected supplemental letter from the CFO"]'::jsonb, 2, 'AU-C 580.20 states that if the auditor concludes that management''s representations are not reliable, the auditor must determine the effect on the audit, including the possibility that sufficient appropriate audit evidence cannot be obtained. Demonstrated dishonesty indicates integrity concerns that permeate all management assertions. The letter is not void per se, and there is no automatic law enforcement reporting requirement under AU-C 580; the core issue is whether any representations can be trusted.', 'hard', 4),

-- Q26: hard / L4 — Initial vs. recurring audit representation considerations
(1, 'Written Representations', 'Langford & Associates is engaged to perform the initial audit of Summit Ridge Inc. for the year ended December 31, 2025. Summit Ridge was previously audited by another firm. The engagement partner considers what additional representations may be needed compared to a recurring engagement. Under AU-C 510 and AU-C 580, in an initial audit the representation letter should additionally address:', '["A detailed comparison of all accounting policies used by the predecessor auditor versus those currently in use", "The predecessor auditor''s opinion on internal controls and whether management disagreed with any findings", "Verification that the predecessor auditor''s workpapers contain no evidence of fraud or material misstatement", "Whether there were any matters that the predecessor auditor communicated to management that could affect the opening balances or the current-year financial statements"]'::jsonb, 3, 'AU-C 510.09 and AU-C 580.A33 address initial audit considerations, requiring the auditor to obtain representations about matters affecting opening balances, including whether prior-period misstatements have been corrected and whether there were matters communicated by the predecessor auditor. A detailed policy comparison or predecessor workpaper guarantee is not required; the focus is on ensuring completeness of information relevant to the current engagement.', 'hard', 4),

-- Q27: medium / L2 — Management bias in estimates representation
(1, 'Written Representations', 'During the 2025 audit of Brookline Pharmaceuticals, the engagement team at Donovan & Park reviews several fair value measurements that involve significant management judgment. The team considers what representation is needed regarding potential bias. Under AU-C 580 and AU-C 540, the auditor should obtain a representation that:', '["Management believes the significant assumptions used in accounting estimates are reasonable and free from intentional bias", "All fair value measurements were calculated using only observable Level 1 market inputs", "An independent valuation firm prepared every estimate to eliminate the possibility of management bias", "The audit committee reviewed and pre-approved every assumption before management recorded the estimates"]'::jsonb, 0, 'AU-C 540.A131 and AU-C 580.A30 support obtaining representations that significant assumptions used in accounting estimates are reasonable and reflect management''s best estimates free from intentional bias. Management judgment is inherent in estimates; the representation addresses the absence of deliberate manipulation. Not all estimates use Level 1 inputs, independent valuators are not always required, and audit committee pre-approval of every assumption is not a prerequisite under the standards.', 'medium', 2),

-- Q28: hard / L4 — Omitted required fraud representation
(1, 'Written Representations', 'During the 2025 audit of Meridian Systems Inc., the engagement partner at Colwell & Shane reviews the signed management representation letter and notices it does not include the required representation about fraud. The CEO explains that including the fraud representation was unnecessary because the entity has a robust anti-fraud program. The partner must determine the appropriate course of action. Under AU-C 580, the auditor should:', '["Accept the omission because an effective anti-fraud program makes the fraud representation redundant", "Inform management that the omitted fraud representation is required by auditing standards and request a revised letter; if management refuses, treat it as a scope limitation", "Proceed with the audit but add a qualification disclosing the absence of the fraud representation", "Issue the report with an other-matter paragraph explaining that management declined one specific representation"]'::jsonb, 1, 'AU-C 580.19-20 requires the auditor to obtain all required written representations, including the fraud representation mandated by AU-C 580.11. The existence of an anti-fraud program does not eliminate the requirement. If management refuses to provide a required representation, the auditor must consider this a scope limitation and evaluate the effect on the opinion, which may result in a qualified opinion or disclaimer of opinion.', 'hard', 4),

-- Q29: medium / L3 — Capital stock/equity transactions representation
(1, 'Written Representations', 'During the 2025 audit of Pinnacle Holdings Corp., which had a complex equity restructuring involving a stock split, treasury stock repurchases, and issuance of convertible preferred shares, the engagement team at Barrett & Langley must ensure the representation letter addresses equity transactions. Under AU-C 580, the auditor should obtain representations that:', '["All share capital transactions have been properly recorded, disclosed, and conducted in accordance with the entity''s articles of incorporation and applicable law", "The entity''s shareholders unanimously approved every equity transaction that occurred during the fiscal year", "No equity transactions have any tax implications that would require disclosure in the income tax footnote", "The entity''s stock transfer agent has independently confirmed every share issuance and repurchase"]'::jsonb, 0, 'AU-C 580.11 and AU-C 580.A29 support obtaining representations that all aspects of equity transactions have been properly recorded and disclosed in conformity with the applicable financial reporting framework and legal requirements. Unanimous shareholder approval is not required for all equity transactions, equity transactions frequently have tax implications requiring disclosure, and transfer agent confirmations are separate evidence from management representations.', 'medium', 3),

-- Q30: medium / L3 — Materiality language in representation letter
(1, 'Written Representations', 'During the 2025 audit of Fieldcrest Analytics Corp., the controller asks the engagement team at Gibson & Tate whether the management representation letter may include a general materiality qualifier limiting representations to material matters only. Under AU-C 580, the auditor should explain that:', '["A general materiality qualifier is required in every representation letter to prevent management from making overly broad assertions", "A materiality qualifier is permissible only if the auditor and management agree on the applicable materiality threshold and it does not exclude required representations", "Materiality qualifiers are always prohibited because they undermine the reliability of all representations in the letter", "Management may unilaterally set the materiality level for the representation letter without consulting the auditor"]'::jsonb, 1, 'AU-C 580.A22-A23 acknowledges that certain representations may be limited to matters that are material, provided the auditor and management have reached an understanding about materiality for this purpose. The qualifier cannot exclude required representations such as fraud or completeness. It is neither universally required nor absolutely prohibited; it is permissible when properly scoped. Management cannot unilaterally define materiality without the auditor''s agreement.', 'medium', 3)
;

COMMIT;
